        RealizedCurrencyTotal: {
            /** @description ISO-4217 of the positions this figure adds up — their own currency, not the base one */
            currency: string;
            /**
             * Format: int64
             * @description Sum of Position.realized_pnl_minor over the positions in `currency`, exact. Null when any of them has no such figure (one sold into another currency); `in_base` is unaffected.
             */
            realized_pnl_minor: number | null;
        };
